    const token = match[1].replace(/^["']+|["']+$/g, "");

    // Save to the active environment and collection.
    pm.environment.set("authToken", token);
    pm.collectionVariables.set("authToken", token);

    console.log("Token captured:", Boolean(token));
    console.log("Environment selected:", pm.environment.name);
} else {
    console.error("No Auth_token value found in the response.");
}

