    pm.expect(match, "Token was not captured from the response").to.not.be.null;
    pm.expect(environmentToken).to.be.a("string").and.not.empty;
    pm.expect(environmentToken).to.equal(match[1].replace(/^["']+|["']+$/g, ""));
});

